class OllamaProvider(BaseProvider):

    def __init__(self):
        self.host = 'http://127.0.0.1:11434'

    def capabilities(self) -> list:
        return ['reasoning', 'coding', 'fast_chat', 'vision', 'local_privacy']

    def health(self) -> Dict[str, Any]:
        return {'provider': 'ollama', 'healthy': True, 'status': 'OPERATIONAL', 'capabilities': self.capabilities()}

    async def generate(self, prompt: str, model: Optional[str]='qwen3:8b', image_bytes: Optional[bytes]=None, capability: str='default') -> ProviderResponse:
        import aiohttp
        start_time = time.perf_counter()
        payload = {'model': model, 'prompt': prompt, 'stream': False}
        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(f'{self.host}/api/generate', json=payload, timeout=120) as resp:
                    elapsed_ms = (time.perf_counter() - start_time) * 1000.0
                    if resp.status == 200:
                        data = await resp.json()
                        return ProviderResponse(ok=True, provider='ollama', model=model, content=data.get('response', ''), latency_ms=round(elapsed_ms, 2))
                    else:
                        return ProviderResponse(ok=False, provider='ollama', model=model, error=f'Ollama HTTP {resp.status}')
        except Exception as e:
            return ProviderResponse(ok=False, provider='ollama', model=model, error=f'Ollama Exception: {str(e)}')

class OllamaProvider(IResearchProvider):
    name: str = 'ollama'

    def __init__(self, base_url: Optional[str]=None, model: Optional[str]=None):
        load_secrets()
        self.base_url = base_url or os.getenv('OLLAMA_BASE_URL', 'http://127.0.0.1:11434')
        self.model = model or os.getenv('OLLAMA_MODEL', 'qwen3:8b')

    async def search(self, query: str, **kwargs: Any) -> Dict[str, Any]:
        """Exécution 100% CPU pure (zéro VRAM, 6 threads, thinking désactivé, budget tokens élevé)."""
        url = f'{self.base_url}/api/generate'
        payload = {'model': self.model, 'prompt': query, 'stream': True, 'think': False, 'options': {'num_gpu': 0, 'num_thread': int(os.getenv('OLLAMA_NUM_THREAD', '6')), 'num_ctx': kwargs.get('num_ctx', 2048), 'num_predict': kwargs.get('max_tokens', 1500), 'temperature': kwargs.get('temperature', 0.7)}}
        timeout = httpx.Timeout(connect=10.0, read=180.0, write=10.0, pool=10.0)
        accumulated_text = []
        last_chunk = {}
        async with httpx.AsyncClient(timeout=timeout) as client:
            async with client.stream('POST', url, json=payload) as response:
                response.raise_for_status()
                async for line in response.aiter_lines():
                    if not line:
                        continue
                    try:
                        chunk = json.loads(line)
                        token = chunk.get('response', '')
                        if token:
                            accumulated_text.append(token)
                        if chunk.get('done', False):
                            last_chunk = chunk
                    except json.JSONDecodeError:
                        continue
        full_response = ''.join(accumulated_text).strip()
        if not full_response:
            return {'provider': self.name, 'model': self.model, 'data': {'text': '[Réponse tronquée : budget de tokens insuffisant pour ce modèle en mode raisonnement]', 'raw': last_chunk}}
        return {'provider': self.name, 'model': self.model, 'data': {'text': full_response, 'raw': last_chunk}}

class OllamaProvider:

    def __init__(self, base_url: str='http://localhost:11434'):
        self.base_url = base_url

    def generate(self, prompt: str, model: str, **kwargs) -> Dict[str, Any]:
        """
        Génère une réponse avec Ollama
        """
        start_time = time.time()
        options = {}
        if 'num_ctx' in kwargs:
            options['num_ctx'] = kwargs['num_ctx']
        if 'num_predict' in kwargs:
            options['num_predict'] = kwargs['num_predict']
        if 'temperature' in kwargs:
            options['temperature'] = kwargs['temperature']
        payload = {'model': model, 'prompt': prompt, 'stream': False, 'options': options}
        try:
            response = requests.post(f'{self.base_url}/api/generate', json=payload, timeout=kwargs.get('timeout', 120))
            response.raise_for_status()
            data = response.json()
            latency_ms = (time.time() - start_time) * 1000
            return {'response': data.get('response', ''), 'latency_ms': latency_ms}
        except Exception as e:
            return {'response': f'Erreur Ollama: {str(e)}', 'latency_ms': (time.time() - start_time) * 1000}
